<script setup lang="ts">
import { Settings2, Check, Download, FileUp, LoaderCircle, ShieldCheck, ArrowUpRight, Sparkles, Database } from 'lucide-vue-next'
const ctx=useQinbian(),settings=ref<any>(),checking=ref(false),connection=ref(''),backing=ref(false),restoring=ref(false),restoreOpen=ref(false),restoreFile=ref<File|null>(null),jobs=ref<any[]>([])
onMounted(async()=>{try{settings.value=await apiFetch('/api/settings');jobs.value=await apiFetch('/api/ai/jobs')}catch(e){ctx.error(e)}})
async function saveModel(){try{await apiFetch('/api/settings',{method:'PATCH',body:{model:settings.value.model}});ctx.notify('默认模型已保存')}catch(e){ctx.error(e)}}
async function check(){checking.value=true;connection.value='';try{const r=await apiFetch<any>('/api/settings/check-ai',{method:'POST'});connection.value=r.ok?'连接正常':'连接未完成'}catch(e:any){connection.value=e.data?.message||'暂时无法连接，请稍后重试'}finally{checking.value=false}}
async function backup(){backing.value=true;try{const blob=await apiFetch('/api/backups',{method:'POST',responseType:'blob'});downloadFile(blob,'秦编备份-'+new Date().toISOString().slice(0,10)+'.zip');ctx.notify('备份已下载')}catch(e){ctx.error(e)}finally{backing.value=false}}
async function restore(){if(!restoreFile.value)return;restoring.value=true;try{const body=new FormData();body.append('file',restoreFile.value);await apiFetch('/api/backups/restore',{method:'POST',body});await ctx.refreshThemes();restoreOpen.value=false;ctx.notify('备份已恢复');settings.value=await apiFetch('/api/settings')}catch(e){ctx.error(e)}finally{restoring.value=false}}
const status=(s:string)=>({queued:'准备中',running:'制作中',validating:'检查中',ready:'候选待确认',failed:'未完成',cancelled:'已取消',applied:'已采用'}[s]||s)
</script>
<template><div class="page settings-page"><header class="page-heading"><div><h1>设置与备份</h1></div></header><template v-if="settings"><section class="settings-section"><div class="settings-section-title"><Sparkles :size="20"/><div><h2>AI 制作</h2><p>DeepSeek</p></div></div><div class="settings-row"><div><h3>默认模型</h3><p>Pro 质量更高，Flash 速度更快。</p></div><UiSelect v-model="settings.model" :options="[{value:'deepseek-v4-pro',label:'DeepSeek V4 Pro'},{value:'deepseek-flash',label:'DeepSeek Flash'}]" aria-label="默认AI模型" @change="saveModel"/></div><div class="settings-row"><div><h3>连接状态</h3><p>{{settings.aiConfigured?'已配置密钥。':'未找到密钥，请在工程根目录的 env 文件中设置 DEEPSEEK_API_KEY。'}}</p><span v-if="connection" class="connection-result">{{connection}}</span></div><button class="btn" :disabled="checking" @click="check"><LoaderCircle v-if="checking" :size="15" class="spin"/><ShieldCheck v-else :size="16"/>{{checking?'正在检查…':'检查连接'}}</button></div><details class="skill-details"><summary>查看制作规范</summary><pre>{{settings.skill}}</pre></details></section><section class="settings-section"><div class="settings-section-title"><Database :size="20"/><div><h2>本地数据</h2><p>文章、组件与图片保存在本机 data/ 目录。</p></div></div><div class="settings-row"><div><h3>完整备份</h3><p>ZIP 文件，包含数据库和全部原图。</p></div><button class="btn" :disabled="backing" @click="backup"><Download :size="16"/>{{backing?'正在打包…':'下载备份'}}</button></div><div class="settings-row"><div><h3>从备份恢复</h3><p>用备份 ZIP 替换当前数据。</p></div><button class="btn" @click="restoreOpen=true"><FileUp :size="16"/>选择文件</button></div></section><section class="settings-section"><div class="settings-section-title"><Settings2 :size="20"/><div><h2>最近的 AI 制作</h2></div></div><div v-if="!jobs.length" class="quiet-note">暂无记录。</div><div v-for="job in jobs" :key="job.id" class="job-history"><div><strong>{{job.result?.name||job.request.prompt.slice(0,40)}}</strong><small>{{formatDate(job.createdAt)}} · {{job.model}} · {{status(job.status)}}</small><p v-if="job.error" class="error-message">{{job.error}}</p></div><details v-if="job.result"><summary>查看结果</summary><div class="history-candidate"><PaletteSwatches v-if="job.result.kind==='palette'" :palette="job.result.palette" compact/><HtmlPreview v-else :html="job.result.html" :max-height="400"/></div></details></div></section><p class="app-version">秦编 1.0</p></template><UiModal v-if="restoreOpen" title="恢复秦编备份" subtitle="当前的文章、组件与图片将被备份内容替换。" @close="!restoring&&(restoreOpen=false)"><div class="form-stack"><label>选择备份文件<input type="file" accept=".zip,application/zip" @change="restoreFile=($event.target as HTMLInputElement).files?.[0]||null"></label><div class="modal-actions"><button class="btn" :disabled="restoring" @click="restoreOpen=false">取消</button><button class="btn primary" :disabled="!restoreFile||restoring" @click="restore">{{restoring?'正在恢复…':'恢复'}}</button></div></div></UiModal></div></template>
